package com.kagafei.g510d2checkout;

import android.Manifest;import android.app.*;import android.os.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.media.AudioManager;import android.media.ToneGenerator;import android.view.*;import android.widget.*;import com.google.zxing.*;import com.journeyapps.barcodescanner.*;import com.journeyapps.barcodescanner.camera.CameraSettings;import java.util.*;

public class MainActivity extends Activity {
 static class P {String n,c;int p,i;P(String n,int p,String c,int i){this.n=n;this.p=p;this.c=c;this.i=i;}}
 final Map<String,P[]> catalog=new LinkedHashMap<>();final Map<String,Integer> cart=new LinkedHashMap<>();final Map<String,P> byCode=new HashMap<>();
 DecoratedBarcodeView scanner;GridLayout grid;TextView cartView,total,status;Spinner cameraSpinner;boolean paused=false,torch=false;String lastCode="";long lastAt=0;
 final ToneGenerator tone=new ToneGenerator(AudioManager.STREAM_MUSIC,75);
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);scanner=findViewById(R.id.barcodeView);grid=findViewById(R.id.grid);cartView=findViewById(R.id.cart);total=findViewById(R.id.total);status=findViewById(R.id.scanStatus);cameraSpinner=findViewById(R.id.cameraSpinner);seed();buildTabs();
  cameraSpinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Camera ID 0","Camera ID 1","Camera ID 2","Camera ID 3"}));
  findViewById(R.id.switchCamera).setOnClickListener(v->startCamera(cameraSpinner.getSelectedItemPosition()));
  findViewById(R.id.pause).setOnClickListener(v->{paused=!paused;if(paused){scanner.pause();status.setText("読取りを停止しています");}else{scanner.resume();status.setText("JANコードを枠内にかざしてください");}});
  findViewById(R.id.torch).setOnClickListener(v->{torch=!torch;if(torch)scanner.setTorchOn();else scanner.setTorchOff();});
  findViewById(R.id.clear).setOnClickListener(v->{cart.clear();refresh();status.setText("JANコードを枠内にかざしてください");});findViewById(R.id.pay).setOnClickListener(v->pay());
  if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA},10);else startCamera(0);show("食品");}
 void seed(){add("食品",new String[]{"食パン","牛乳","たまご","おにぎり","カレー","ヨーグルト"},new int[]{198,218,298,138,258,158},new String[]{"4901234500006","4901234500013","4901234500020","4901234500037","4901234500044","4901234500051"},new int[]{R.drawable.bread,R.drawable.milk,R.drawable.eggs,R.drawable.onigiri,R.drawable.curry,R.drawable.yogurt});add("飲料",new String[]{"緑茶","水","コーヒー","オレンジジュース","コーラ","炭酸水"},new int[]{128,108,148,198,168,118},codes(6),new int[]{R.drawable.green_tea,R.drawable.water,R.drawable.coffee,R.drawable.orange_juice,R.drawable.cola,R.drawable.sparkling_water});add("青果",new String[]{"りんご","バナナ","みかん","トマト","キャベツ","じゃがいも"},new int[]{158,198,398,258,198,298},codes(12),new int[]{R.drawable.apple,R.drawable.banana,R.drawable.mandarin,R.drawable.tomato,R.drawable.cabbage,R.drawable.potato});add("日用品",new String[]{"ティッシュ","洗剤","歯ブラシ","ラップ","スポンジ","ごみ袋"},new int[]{398,348,198,258,128,298},codes(18),new int[]{R.drawable.tissue,R.drawable.detergent,R.drawable.toothbrush,R.drawable.wrap,R.drawable.sponge,R.drawable.garbage_bag});add("精肉・鮮魚",new String[]{"牛肉","豚肉","鶏もも肉","生鮭","えび","ひき肉"},new int[]{680,480,398,580,498,458},codes(24),new int[]{R.drawable.beef,R.drawable.pork,R.drawable.chicken,R.drawable.salmon,R.drawable.shrimp,R.drawable.minced_meat});add("惣菜",new String[]{"幕の内弁当","寿司盛合せ","唐揚げ","ポテトサラダ","サンドイッチ","プリン"},new int[]{598,798,398,258,328,198},codes(30),new int[]{R.drawable.bento,R.drawable.sushi_pack,R.drawable.karaage,R.drawable.potato_salad,R.drawable.sandwich,R.drawable.pudding});}
 String[] codes(int start){String[] a=new String[6];for(int i=0;i<6;i++)a[i]=ean("49012345"+String.format(Locale.US,"%04d",start+i));return a;}String ean(String twelve){int sum=0;for(int i=0;i<12;i++)sum+=(twelve.charAt(i)-'0')*(i%2==0?1:3);return twelve+((10-sum%10)%10);}void add(String k,String[] n,int[] p,String[] c,int[] im){P[] a=new P[6];for(int j=0;j<6;j++){a[j]=new P(n[j],p[j],c[j],im[j]);byCode.put(c[j],a[j]);}catalog.put(k,a);}
 void buildTabs(){LinearLayout tabs=findViewById(R.id.tabs);for(String k:catalog.keySet()){Button b=new Button(this);b.setText(k);b.setTextSize(14);b.setOnClickListener(v->show(k));tabs.addView(b,new LinearLayout.LayoutParams(150,-1));}}
 void startCamera(int id){scanner.pause();CameraSettings cs=new CameraSettings();cs.setRequestedCameraId(id);scanner.getBarcodeView().setCameraSettings(cs);scanner.getBarcodeView().setDecoderFactory(new DefaultDecoderFactory(Arrays.asList(BarcodeFormat.EAN_13,BarcodeFormat.EAN_8,BarcodeFormat.UPC_A,BarcodeFormat.QR_CODE)));scanner.decodeContinuous(new BarcodeCallback(){public void barcodeResult(BarcodeResult r){handle(r.getText());}public void possibleResultPoints(List<ResultPoint> p){}});scanner.resume();status.setText("Camera ID "+id+" で読取り中");}
 void handle(String code){long now=System.currentTimeMillis();if(code.equals(lastCode)&&now-lastAt<2500)return;lastCode=code;lastAt=now;P p=byCode.get(code);if(p==null){status.setText("未登録JAN: "+code);tone.startTone(ToneGenerator.TONE_PROP_NACK,120);return;}cart.put(p.c,cart.getOrDefault(p.c,0)+1);status.setText(p.n+"  "+p.p+"円を登録しました");tone.startTone(ToneGenerator.TONE_PROP_BEEP,100);refresh();}
 void show(String k){grid.removeAllViews();for(P p:catalog.get(k)){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(4,4,4,4);card.setBackgroundColor(Color.WHITE);GridLayout.LayoutParams q=new GridLayout.LayoutParams();q.width=0;q.height=0;q.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);q.rowSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);q.setMargins(4,4,4,4);card.setLayoutParams(q);ImageView im=new ImageView(this);im.setImageResource(p.i);im.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(im,new LinearLayout.LayoutParams(-1,0,1f));Button bt=new Button(this);bt.setText(p.n+" "+p.p+"円 ＋");bt.setTextSize(13);bt.setOnClickListener(v->handle(p.c));card.addView(bt,new LinearLayout.LayoutParams(-1,52));grid.addView(card);}}
 void refresh(){int sum=0;StringBuilder s=new StringBuilder();for(String code:cart.keySet()){P p=byCode.get(code);int q=cart.get(code);sum+=p.p*q;s.append(p.n).append(" × ").append(q).append("\n");}cartView.setText(cart.isEmpty()?"商品はありません":s);total.setText("合計 "+(sum+(int)(sum*.1))+"円");}
 void pay(){if(cart.isEmpty()){status.setText("商品を登録してください");return;}String[] x={"クレジットカード","電子マネー","QRコード","現金"};new AlertDialog.Builder(this).setTitle("お支払い方法").setItems(x,(d,w)->new AlertDialog.Builder(this).setTitle("会計完了").setMessage(x[w]+"でお支払いを受け付けました").setPositiveButton("完了",(a,z)->{cart.clear();refresh();status.setText("ありがとうございました");}).show()).show();}
 @Override protected void onResume(){super.onResume();if(!paused&&checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)scanner.resume();}@Override protected void onPause(){scanner.pause();super.onPause();}@Override protected void onDestroy(){tone.release();super.onDestroy();}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==10&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)startCamera(0);else status.setText("カメラ権限が必要です");}
}
